CREATE OR REPLACE FUNCTION public.is_store_member(p_store_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE store_id=p_store_id AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_store_member(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_store_member(uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.get_user_store_id(_user_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.store_id FROM public.user_roles r LEFT JOIN public.profiles p ON p.user_id=r.user_id WHERE r.user_id=_user_id ORDER BY (r.store_id=p.store_id) DESC NULLS LAST,r.id LIMIT 1 $$;
DO $migration$ DECLARE p record; q text; c text; BEGIN FOR p IN SELECT * FROM pg_policies WHERE schemaname='public' AND (qual LIKE '%get_user_store_id(auth.uid())%' OR with_check LIKE '%get_user_store_id(auth.uid())%') LOOP q:=regexp_replace(p.qual, '([a-z_][a-z_0-9.]* = get_user_store_id\(auth.uid\(\)\))', 'public.is_store_member(\1)', 'g'); c:=regexp_replace(p.with_check, '([a-z_][a-z_0-9.]* = get_user_store_id\(auth.uid\(\)\))', 'public.is_store_member(\1)', 'g'); q:=replace(q, ' = get_user_store_id(auth.uid())',''); c:=replace(c, ' = get_user_store_id(auth.uid())',''); EXECUTE format('ALTER POLICY %I ON public.%I%s%s',p.policyname,p.tablename,CASE WHEN q IS NOT NULL THEN ' USING ('||q||')' ELSE '' END,CASE WHEN c IS NOT NULL THEN ' WITH CHECK ('||c||')' ELSE '' END); END LOOP; END $migration$;
CREATE POLICY "Users can read own store memberships" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER POLICY "Store members can view store profiles" ON public.profiles USING(EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=profiles.user_id AND public.is_store_member(r.store_id)));
CREATE OR REPLACE FUNCTION public.owner_entitlement(p_owner_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; BEGIN IF EXISTS(SELECT 1 FROM profiles WHERE user_id=p_owner_id AND lifetime_access) THEN RETURN jsonb_build_object('active',true,'plan','enterprise','stores',2147483647,'staff',2147483647,'lifetime',true); END IF; SELECT sub.* INTO s FROM subscriptions sub JOIN stores st ON st.id=sub.store_id WHERE st.owner_id=p_owner_id AND sub.status='active' AND sub.expires_at>now() ORDER BY CASE sub.plan::text WHEN 'enterprise' THEN 4 WHEN 'biz_pro' THEN 3 WHEN 'business' THEN 2 ELSE 1 END DESC,sub.expires_at DESC LIMIT 1; IF FOUND THEN RETURN jsonb_build_object('active',true,'plan',s.plan,'stores',CASE s.plan::text WHEN 'enterprise' THEN 2147483647 WHEN 'biz_pro' THEN 5 WHEN 'business' THEN 3 ELSE 1 END,'staff',CASE s.plan::text WHEN 'enterprise' THEN 2147483647 WHEN 'biz_pro' THEN 10 WHEN 'business' THEN 3 ELSE 0 END,'expires_at',s.expires_at); END IF; RETURN jsonb_build_object('active',false,'plan','starter','stores',1,'staff',0); END $$;
REVOKE ALL ON FUNCTION public.owner_entitlement(uuid) FROM PUBLIC, authenticated; GRANT EXECUTE ON FUNCTION public.owner_entitlement(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.get_store_entitlement(p_store_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE st stores; e jsonb; BEGIN IF NOT public.is_store_member(p_store_id) THEN RAISE EXCEPTION 'Not a store member'; END IF; SELECT * INTO st FROM stores WHERE id=p_store_id; e:=public.owner_entitlement(st.owner_id); RETURN e || jsonb_build_object('active',(e->>'active')::boolean OR st.trial_ends_at>now(),'is_trialing',NOT (e->>'active')::boolean AND st.trial_ends_at>now(),'trial_ends_at',st.trial_ends_at); END $$;
REVOKE ALL ON FUNCTION public.get_store_entitlement(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_store_entitlement(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_store_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; n integer; BEGIN IF TG_OP='UPDATE' AND NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN RAISE EXCEPTION 'Store ownership cannot be changed'; END IF; IF TG_OP='UPDATE' THEN RETURN NEW; END IF; PERFORM pg_advisory_xact_lock(hashtext(NEW.owner_id::text)); e:=public.owner_entitlement(NEW.owner_id); SELECT count(*) INTO n FROM stores WHERE owner_id=NEW.owner_id; IF n >= (e->>'stores')::integer THEN RAISE EXCEPTION 'Store limit reached. Upgrade your subscription to add more stores.'; END IF; IF length(trim(NEW.name))=0 OR length(NEW.name)>100 THEN RAISE EXCEPTION 'Store name must be 1 to 100 characters'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_owned_store_limit BEFORE INSERT OR UPDATE ON public.stores FOR EACH ROW EXECUTE FUNCTION public.enforce_store_limit();
CREATE OR REPLACE FUNCTION public.create_owned_store(p_name text,p_address text,p_phone text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE st uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF length(trim(p_name)) NOT BETWEEN 1 AND 100 OR length(trim(p_address)) NOT BETWEEN 1 AND 255 OR length(coalesce(p_phone,''))>40 THEN RAISE EXCEPTION 'Invalid store details'; END IF; INSERT INTO stores(name,address,phone,owner_id,printer_type) VALUES(trim(p_name),trim(p_address),nullif(trim(p_phone),''),auth.uid(),'58mm') RETURNING id INTO st; INSERT INTO user_roles(user_id,store_id,role) VALUES(auth.uid(),st,'owner'); UPDATE profiles SET store_id=st WHERE user_id=auth.uid(); PERFORM seed_role_permissions(st); RETURN st; END $$;
REVOKE ALL ON FUNCTION public.create_owned_store(text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_owned_store(text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_staff_limit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; owner uuid; n integer; BEGIN SELECT owner_id INTO owner FROM stores WHERE id=NEW.store_id; IF NEW.role='owner' THEN IF NEW.user_id<>owner THEN RAISE EXCEPTION 'Only the store owner may hold the owner role'; END IF; RETURN NEW; END IF; IF NEW.user_id=owner THEN RAISE EXCEPTION 'Cannot change the store owner role'; END IF; IF TG_OP='UPDATE' AND NEW.store_id=OLD.store_id AND OLD.role<>'owner' THEN RETURN NEW; END IF; PERFORM pg_advisory_xact_lock(hashtext(NEW.store_id::text)); e:=public.owner_entitlement(owner); SELECT count(*) INTO n FROM user_roles WHERE store_id=NEW.store_id AND role<>'owner'; IF n >= (e->>'staff')::integer THEN RAISE EXCEPTION 'Staff limit reached for this store. Upgrade your subscription.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_store_staff_limit BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.enforce_staff_limit();
CREATE OR REPLACE FUNCTION public.assign_staff_to_store(p_user_id uuid,p_source_store uuid,p_target_store uuid,p_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_role='owner' THEN RAISE EXCEPTION 'Invalid staff role'; END IF; IF NOT EXISTS(SELECT 1 FROM stores WHERE id=p_source_store AND owner_id=auth.uid()) OR NOT EXISTS(SELECT 1 FROM stores WHERE id=p_target_store AND owner_id=auth.uid()) OR NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=p_user_id AND store_id=p_source_store AND role<>'owner') THEN RAISE EXCEPTION 'Only owners can assign their existing staff to their stores'; END IF; INSERT INTO user_roles(user_id,store_id,role) VALUES(p_user_id,p_target_store,p_role) ON CONFLICT(user_id,store_id) DO UPDATE SET role=excluded.role; END $$;
REVOKE ALL ON FUNCTION public.assign_staff_to_store(uuid,uuid,uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.assign_staff_to_store(uuid,uuid,uuid,public.app_role) TO authenticated;
CREATE TABLE public.subscription_checkouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL REFERENCES public.stores(id),owner_id uuid NOT NULL,plan public.subscription_plan NOT NULL,billing_cycle text NOT NULL,amount integer NOT NULL,reference text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),activated_at timestamptz);
GRANT SELECT ON public.subscription_checkouts TO authenticated; GRANT ALL ON public.subscription_checkouts TO service_role;
ALTER TABLE public.subscription_checkouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners can read their checkouts" ON public.subscription_checkouts FOR SELECT TO authenticated USING(owner_id=auth.uid());
DROP POLICY "Store owners can create subscriptions" ON public.subscriptions; DROP POLICY "Store owners can update subscriptions" ON public.subscriptions;
REVOKE INSERT,UPDATE ON public.subscriptions FROM authenticated;
CREATE OR REPLACE FUNCTION public.activate_subscription_checkout(p_reference text,p_amount integer,p_currency text,p_store_id uuid,p_owner_id uuid,p_plan text,p_cycle text,p_paid_at timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c subscription_checkouts; expiry timestamptz; BEGIN SELECT * INTO c FROM subscription_checkouts WHERE reference=p_reference FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Checkout not found'; END IF; IF p_amount<>c.amount OR p_currency<>'NGN' OR p_store_id<>c.store_id OR p_owner_id<>c.owner_id OR p_plan<>c.plan::text OR p_cycle<>c.billing_cycle THEN RAISE EXCEPTION 'Payment details do not match checkout'; END IF; IF c.status='active' THEN RETURN jsonb_build_object('success',true,'plan',c.plan); END IF; expiry:=p_paid_at + CASE c.billing_cycle WHEN 'yearly' THEN interval '365 days' WHEN 'six_months' THEN interval '6 months' ELSE interval '30 days' END; INSERT INTO subscriptions(store_id,plan,status,paystack_reference,amount,currency,started_at,expires_at,updated_at) VALUES(c.store_id,c.plan,'active',c.reference,c.amount,'NGN',p_paid_at,expiry,now()) ON CONFLICT(store_id) DO UPDATE SET plan=excluded.plan,status=excluded.status,paystack_reference=excluded.paystack_reference,amount=excluded.amount,currency=excluded.currency,started_at=excluded.started_at,expires_at=excluded.expires_at,updated_at=now(); UPDATE subscription_checkouts SET status='active',activated_at=now() WHERE id=c.id; RETURN jsonb_build_object('success',true,'plan',c.plan,'expires_at',expiry); END $$;
REVOKE ALL ON FUNCTION public.activate_subscription_checkout(text,integer,text,uuid,uuid,text,text,timestamptz) FROM PUBLIC,authenticated; GRANT EXECUTE ON FUNCTION public.activate_subscription_checkout(text,integer,text,uuid,uuid,text,text,timestamptz) TO service_role;